INSERT IGNORE INTO `data_sources` (`id`, `title`, `publisher`, `year`, `url`, `kind`, `trust`, `note`, `accessed_at`, `is_custom`) VALUES ('nso-2025', 'Thông cáo báo chí về tình hình dân số, lao động, việc làm quý IV và năm 2025', 'Cục Thống kê – Bộ Tài chính', 2025, 'https://www.nso.gov.vn/tin-tuc-thong-ke/2026/01/thong-cao-bao-chi-ve-tinh-hinh-dan-so-lao-dong-viec-lam-quy-iv-va-nam-2025/', 'thong-ke', 'cao', 'Số liệu điều tra lao động – việc làm toàn quốc. Thu nhập bình quân tính cho toàn bộ lao động, không tách theo ngành học hay trình độ đào tạo — chỉ dùng làm mốc so sánh.', '2026-09-28 17:00:00.000', 0);
INSERT IGNORE INTO `data_sources` (`id`, `title`, `publisher`, `year`, `url`, `kind`, `trust`, `note`, `accessed_at`, `is_custom`) VALUES ('tt-01-2024', 'Thông tư 01/2024/TT-BGDĐT ban hành Chuẩn cơ sở giáo dục đại học', 'Bộ Giáo dục và Đào tạo', 2024, 'https://thuvienphapluat.vn/van-ban/Giao-duc/Thong-tu-01-2024-TT-BGDDT-Chuan-co-so-giao-duc-dai-hoc-598459.aspx', 'van-ban', 'cao', 'Chuẩn yêu cầu tỷ lệ người tốt nghiệp có việc làm phù hợp với trình độ, tự tạo việc làm hoặc học tiếp trong 12 tháng không thấp hơn 70%; trường công bố kết quả thực hiện chuẩn hằng năm.', '2026-09-28 17:00:00.000', 0);
INSERT IGNORE INTO `data_sources` (`id`, `title`, `publisher`, `year`, `url`, `kind`, `trust`, `note`, `accessed_at`, `is_custom`) VALUES ('tt-09-2024', 'Thông tư 09/2024/TT-BGDĐT quy định về công khai trong hoạt động của các cơ sở giáo dục', 'Bộ Giáo dục và Đào tạo', 2024, 'https://thuvienphapluat.vn/van-ban/Giao-duc/Thong-tu-09-2024-TT-BGDDT-cong-khai-trong-hoat-dong-co-so-giao-duc-quoc-dan-581008.aspx', 'van-ban', 'cao', 'Điều 13: cơ sở giáo dục đại học phải công khai tỷ lệ người học tốt nghiệp có việc làm phù hợp với trình độ đào tạo trong 12 tháng sau tốt nghiệp. Đây là nguồn chính thức nên dùng cho số liệu theo từng trường, ngành.', '2026-09-28 17:00:00.000', 0);
INSERT IGNORE INTO `data_sources` (`id`, `title`, `publisher`, `year`, `url`, `kind`, `trust`, `note`, `accessed_at`, `is_custom`) VALUES ('tuoitre-2026-01-viec-lam', 'Trường đại học nào nhiều sinh viên sớm có việc làm, lương cao sau khi ra trường?', 'Báo Tuổi Trẻ (21/01/2026)', 2025, 'https://tuoitre.vn/truong-dai-hoc-nao-nhieu-sinh-vien-som-co-viec-lam-luong-cao-sau-khi-ra-truong-20260121180410959.htm', 'bao-chi', 'trung-binh', 'Báo chí tổng hợp kết quả khảo sát do chính các trường thực hiện với sinh viên tốt nghiệp năm 2025. Nên đối chiếu báo cáo gốc của trường; tỷ lệ phản hồi và cách định nghĩa "có việc làm" khác nhau giữa các trường.', '2026-09-28 17:00:00.000', 0);
INSERT IGNORE INTO `data_sources` (`id`, `title`, `publisher`, `year`, `url`, `kind`, `trust`, `note`, `accessed_at`, `is_custom`) VALUES ('trovio-demo', 'Số liệu minh hoạ của bản demo Trovio', 'Trovio', 2025, NULL, 'minh-hoa', 'minh-hoa', 'Ước lượng chỉ để minh hoạ giao diện, KHÔNG phải số liệu thống kê. Cần thay bằng số liệu từ báo cáo khảo sát việc làm của các trường hoặc khảo sát có phương pháp công bố rõ ràng.', '2026-09-28 17:00:00.000', 0);
