INSERT IGNORE INTO `timeline_config` (`id`, `season`, `official`, `source_url`, `note`, `updated_at`, `updated_by`) VALUES (1, '2026', 0, NULL, 'Lịch mùa tuyển sinh 2026 theo hướng dẫn của Bộ GD&ĐT (Thông tư 06/2026/TT-BGDĐT).', '2026-10-14 02:43:21.946', NULL);
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-dgnl-hn-dot-1', 'Thi đánh giá năng lực ĐHQG Hà Nội (HSA) — đợt đầu', '2026-03-13 17:00:00.000', '2026-03-14 17:00:00.000', 'dgnl', 'Các đợt thi HSA thường bắt đầu từ tháng 3. Đăng ký trên cổng thi của ĐHQG Hà Nội trước ngày thi vài tuần.');
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-dgnl-hcm-dot-1', 'Thi đánh giá năng lực ĐHQG TP.HCM — đợt 1', '2026-04-04 17:00:00.000', NULL, 'dgnl', 'Kỳ thi thang 1200 điểm, thường tổ chức 2 đợt vào tháng 4 và tháng 5–6.');
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-dang-ky-thi-thpt', 'Đăng ký dự thi tốt nghiệp THPT', '2026-04-20 17:00:00.000', '2026-05-04 17:00:00.000', 'dang-ky', 'Học sinh lớp 12 đăng ký dự thi qua trường THPT hoặc trực tuyến trên hệ thống của Bộ.');
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-thi-thpt', 'Kỳ thi tốt nghiệp THPT', '2026-06-24 17:00:00.000', '2026-06-25 17:00:00.000', 'thi', 'Hai ngày thi chính thức. Mang theo giấy báo dự thi và giấy tờ tuỳ thân.');
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-cong-bo-diem', 'Công bố điểm thi tốt nghiệp THPT', '2026-07-15 17:00:00.000', NULL, 'ket-qua', 'Tra cứu điểm thi, sau đó cập nhật điểm vào Trovio để xem lại mức cạnh tranh tham khảo.');
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-dang-ky-nguyen-vong', 'Đăng ký & điều chỉnh nguyện vọng xét tuyển', '2026-07-17 17:00:00.000', '2026-07-29 17:00:00.000', 'dang-ky', 'Đăng ký tối đa 15 nguyện vọng theo Quy chế tuyển sinh 2026 (Thông tư 06/2026/TT-BGDĐT), sắp xếp theo mức độ mong muốn thực tế. Dùng “Kiểm tra danh sách” ở trang Đã lưu trước khi nộp.');
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-nop-le-phi', 'Nộp lệ phí xét tuyển trực tuyến', '2026-07-30 17:00:00.000', '2026-08-05 17:00:00.000', 'dang-ky', 'Nộp đúng số lượng nguyện vọng đã đăng ký. Nguyện vọng chưa nộp lệ phí sẽ không được xét.');
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-ket-qua-dot-1', 'Công bố kết quả trúng tuyển đợt 1', '2026-08-19 17:00:00.000', NULL, 'ket-qua', 'Mỗi thí sinh chỉ trúng tuyển 1 nguyện vọng — nguyện vọng có thứ tự ưu tiên cao nhất mà bạn đủ điều kiện.');
INSERT IGNORE INTO `timeline_events` (`id`, `title`, `start_date`, `end_date`, `category`, `description`) VALUES ('2026-xac-nhan-nhap-hoc', 'Xác nhận nhập học trực tuyến', '2026-08-20 17:00:00.000', '2026-08-29 17:00:00.000', 'nhap-hoc', 'Xác nhận nhập học trên hệ thống của Bộ trước hạn, sau đó làm thủ tục theo hướng dẫn của trường.');
